  "oral", "tablet", "tablets", "tab", "tabs", "capsule", "capsules", "cap", "caps", "extended", "delayed", "release",
  "solution", "suspension", "injection", "injectable", "pen", "injector", "prefilled", "syringe", "auto-injector",
